import json

import django.core.serializers.json
from django.db import migrations, models

from cmj.utils import run_sql


def populate_extra_data_json(apps, schema_editor):
    documentos = run_sql(
        "select id, extra_data from sigad_documento where extra_data is not null"
    )

    Documento = apps.get_model("sigad", "Documento")

    for doc in documentos:
        doc_id = doc[0]
        extra_data = doc[1]
        if extra_data == "{}" or not extra_data:
            continue
        try:
            extra_data_json = json.loads(extra_data)
        except (json.JSONDecodeError, TypeError):
            try:
                extra_data_json = eval(extra_data)

                if extra_data_json is None:
                    continue

                Documento.objects.filter(id=doc_id).update(
                    extra_data_json=extra_data_json
                )

            except Exception:
                pass

        # Documento.objects.filter(id=doc_id).update(extra_data=None)

    run_sql("""
        delete from sigad_documento
        where id >= 118982 and classe_id=233
    """)


